// Generated by Phase 01-02 extraction. Behavior-preserving move from the index.html monolith.

// D3 force simulation, rendering, motion, tooltips, highlighting.
/* global d3 */
import { STATE, syncUrlState } from "../state.js";
import { DATA, asCountryName, graphForMode, sourceYear } from "../data/index.js";
import { updateCompanyCard, updateCompareButton, openProfile, hideSearchPopovers, jump } from "../ui/index.js";
import { provenanceFor, renderProvenanceBadge, badgeHtml, confidenceScore } from "../trust/index.js";

// D3 / SVG singletons (DOM exists at module eval time — modules are deferred).
const W = innerWidth;
const H = innerHeight;
const svg = d3.select("#canvas").attr("width", W).attr("height", H);
const defs = svg.append("defs");
defs.append("marker").attr("id", "a").attr("viewBox", "0 -3 7 6").attr("refX", 16).attr("refY", 0).attr("markerWidth", 4).attr("markerHeight", 4).attr("orient", "auto")
  .append("path").attr("d", "M0,-2.5L7,0L0,2.5").attr("fill", "#2a2a2a");
const g = svg.append("g");
const zoom = d3.zoom().scaleExtent([0.12, 6]).on("zoom", (e) => g.attr("transform", e.transform));
svg.call(zoom);

// Touch-tap recovery for nodes: d3.drag() preventDefaults touchstart and thus
// suppresses the synthesized click on touch. We detect a stationary touch
// gesture in the drag `end` handler (< TAP_SLOP px) and activate the node there.
const TAP_SLOP = 10; // px: movement above this is a drag, not a tap
let nodeDragStart = null;

// DOM render targets owned by viz.
const tt = document.getElementById("tt");
const productTitleEl = document.getElementById("productTitle");
const subtitleEl = document.getElementById("dynamicSubtitle");
const hintEl = document.getElementById("hint");
const legendEl = document.getElementById("lg");
const layerEl = document.getElementById("ly");
const countryBtns = document.getElementById("countryBtns");

// Mutable D3 selections — reassigned by updateGraph() on every view change. The on("tick")
// handler in buildSimulation reads these module-level bindings (never a stale closure copy).
let nodeSel;
let linkSel;
let labelSel;
let subSel;
let particleLayer;

// Reduced-motion guard for the D3 (JS-driven) transition path. The CSS @media block in
// theme.css covers DOM transitions; this gates D3 .transition().duration(...) on view change.
const prefersReducedMotion = () =>
  (typeof window !== "undefined" && window.matchMedia)
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

function animateCounter(elementId, target, duration = 1000, prefix = '', suffix = '') {
  const el = document.getElementById(elementId);
  if (!el) return;
  
  const start = 0;
  const startTime = performance.now();
  const easeOutQuad = t => t * (2 - t);
  
  function update(currentTime) {
    const elapsed = currentTime - startTime;
    const progress = Math.min(elapsed / duration, 1);
    const eased = easeOutQuad(progress);
    const current = Math.floor(start + (target - start) * eased);
    
    el.textContent = prefix + current.toLocaleString() + suffix;
    
    if (progress < 1) {
      requestAnimationFrame(update);
    }
  }
  
  requestAnimationFrame(update);
}

function updateStatsAnimated(nodes, links, countries, layers, marketCap) {
  animateCounter('sN', nodes.length, 800);
  animateCounter('sL', links.length, 800);
  animateCounter('sC', countries, 800);
  animateCounter('sY', layers, 800);
  animateCounter('sM', marketCap, 1000, '$', 'T');
}

function updateStats() {
  const countryCount = new Set(STATE.nodes.map((n) => n.c)).size;
  const layerCount = Object.keys(STATE.layerMap).length;
  const totalCap = STATE.nodes.filter(n => n.marketcap).reduce((sum, n) => sum + n.marketcap, 0);
  const marketCapT = totalCap / 1e12;
  
  // Use animated counter function
  animateCounter('sN', STATE.nodes.length, 800);
  animateCounter('sL', STATE.links.length, 800);
  animateCounter('sC', countryCount, 800);
  animateCounter('sY', layerCount, 800);
  animateCounter('sM', marketCapT, 1000, '$', 'T');

  // $cap is dataset-level OBSERVED, sourced from meta (companiesmarketcap.com).
  // Counts (#sN/#sL/#sC/#sY) are derived aggregates -> intentionally UNBADGED (RESEARCH Q1).
  const capEl = document.getElementById('sM');
  if (capEl && capEl.parentElement) {
    const capProv = provenanceFor({ marketcap: true }, { meta: DATA.meta });
    let badge = capEl.parentElement.querySelector('.cap-prov');
    if (!badge) {
      badge = document.createElement('span');
      badge.className = 'cap-prov';
      capEl.parentElement.appendChild(badge);
    }
    renderProvenanceBadge(badge, capProv);
  }
}

function buildLegend() {
  legendEl.innerHTML = "";
  
  // Q6: Node type counts
  const typeCounts = {
    company: STATE.nodes.filter(n => n.kind === 'company').length,
    supplier: STATE.nodes.filter(n => n.kind === 'supplier').length,
    service: STATE.nodes.filter(n => n.kind === 'service').length,
    channel: STATE.nodes.filter(n => n.kind === 'channel').length,
    demand: STATE.nodes.filter(n => n.kind === 'demand').length
  };
  
  const typeHeader = document.createElement('div');
  typeHeader.style.cssText = 'font-size:8px;color:#666;text-transform:uppercase;margin-bottom:4px';
  typeHeader.textContent = 'Node Types';
  legendEl.appendChild(typeHeader);
  
  Object.entries(typeCounts).forEach(([type, count]) => {
    if (count > 0) {
      const li = document.createElement("div");
      li.style.cssText = 'font-size:9px;color:#888;margin-bottom:2px';
      li.innerHTML = `${type}: <b style="color:#aaa">${count}</b>`;
      legendEl.appendChild(li);
    }
  });
  
  // Country section
  const countryHeader = document.createElement('div');
  countryHeader.style.cssText = 'font-size:8px;color:#666;text-transform:uppercase;margin:8px 0 4px';
  countryHeader.textContent = 'Countries';
  legendEl.appendChild(countryHeader);
  
  const used = [...new Set(STATE.nodes.map((n) => n.c))];
  used.forEach((code) => {
    const li = document.createElement("div");
    li.className = "li";
    const color = DATA.countries[code]?.c || "#777";
    li.innerHTML = `<span class="ld" style="background:${color}"></span>${code} ${asCountryName(code)}`;
    legendEl.appendChild(li);
  });
}

function buildLayerSidebar() {
  layerEl.innerHTML = "";
  const keys = [...new Set(STATE.nodes.map((n) => n.layer))].sort((a, b) => a - b);
  keys.forEach((layer) => {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "lb";
    b.textContent = `${layer} / ${STATE.layerMap[layer] || ""}`;
    b.setAttribute("aria-label", `Highlight layer ${layer}`);
    b.onclick = () => highlightBy((n) => n.layer === layer);
    layerEl.appendChild(b);
  });
}

function buildCountryButtons() {
  countryBtns.innerHTML = "";
  if (STATE.mode !== "global") return;
  const counts = d3.rollups(STATE.nodes, (v) => v.length, (d) => d.c).sort((a, b) => b[1] - a[1]).slice(0, 8);
  counts.forEach(([code]) => {
    const b = document.createElement("button");
    b.type = "button";
    b.textContent = code;
    b.setAttribute("aria-label", `Highlight country ${code}`);
    b.onclick = () => highlightBy((n) => n.c === code);
    countryBtns.appendChild(b);
  });
  const all = document.createElement("button");
  all.type = "button";
  all.textContent = "All";
  all.setAttribute("aria-label", "Reset country highlight");
  all.onclick = () => resetHighlight();
  countryBtns.appendChild(all);
}

function clearGraph() {
  if (STATE.simulation) STATE.simulation.stop();
  if (STATE.particleTimer) cancelAnimationFrame(STATE.particleTimer);
  if (STATE.settleTimer) clearTimeout(STATE.settleTimer);
  g.selectAll("*").remove();
  STATE.particleTimer = null;
  STATE.settleTimer = null;
  STATE.particlesOn = false;
  STATE.lockId = null;
  tt.style.display = "none";
}

function showTooltip(d, ev) {
  const tt = document.getElementById('tt');

  // Provenance is derived centrally by the trust core — no inline confidence parsing.
  const prov = provenanceFor(d, { sourceIndex: STATE.sourceIndex, meta: DATA.meta });
  const verified = Boolean(prov.source);

  // Live confidence score: nowYear from meta.generatedAt (never hardcoded); the figure's
  // source year resolves its FK so older sources decay (see js/trust confidenceScore).
  const nowYear = new Date(DATA.meta?.generatedAt || Date.now()).getUTCFullYear();
  const src = STATE.sourceIndex?.[d.sourceId ?? d.sf];
  const score = confidenceScore(d, {
    sourceIndex: STATE.sourceIndex,
    meta: DATA.meta,
    sourceYear: src ? sourceYear(src, nowYear) : null,
    now: nowYear,
  });

  // Helper to format value
  const formatValue = (v) => {
    if (typeof v === 'number') {
      if (v >= 1e12) return '$' + (v / 1e12).toFixed(2) + 'T';
      if (v >= 1e9) return '$' + (v / 1e9).toFixed(2) + 'B';
      if (v >= 1e6) return '$' + (v / 1e6).toFixed(2) + 'M';
      return '$' + v.toFixed(2);
    }
    return v;
  };
  
  tt.innerHTML = `
    <div class="tn">${(d.l || d.label || d.id || '').replace("\n", " - ")}</div>
    <div class="tf">${d.kind || 'Node'} · ${badgeHtml(prov)} · Confidence: ${score}%</div>
    <div class="td">
      <div class="td-col">
        ${d.country || d.c ? `
          <div class="td-item">
            <span class="td-label">Country</span>
            <span class="td-value">${d.country || asCountryName(d.c)}</span>
          </div>
        ` : ''}
        ${d.type ? `
          <div class="td-item">
            <span class="td-label">Type</span>
            <span class="td-value">${d.type}</span>
          </div>
        ` : ''}
      </div>
      <div class="td-col">
        ${d.value ? `
          <div class="td-item">
            <span class="td-label">Value</span>
            <span class="td-value">${formatValue(d.value)}</span>
          </div>
        ` : ''}
        ${verified ? `
          <div class="td-item">
            <span class="td-label">Source</span>
            <span class="td-value">✓ Verified</span>
          </div>
        ` : ''}
      </div>
    </div>
    ${prov.source ? `
      <div class="tu">
        <a href="${prov.source.url}" target="_blank" rel="noopener noreferrer" class="source-link">View Source →</a>
      </div>
    ` : ''}
  `;

  moveTooltip(ev);
  tt.style.display = 'block';
}

function linkNodeLabel(endpoint) {
  if (!endpoint) return "Unknown";
  const node = typeof endpoint === "object" ? endpoint : STATE.nodes.find((n) => n.id === endpoint);
  if (!node) return "Unknown";
  return (node.l || node.id || "Unknown").split("\n")[0];
}

function showLinkTooltip(d, ev) {
  const tt = document.getElementById('tt');

  // Provenance derived centrally from d.cf/d.sf by the trust core.
  const prov = provenanceFor(d, { sourceIndex: STATE.sourceIndex, meta: DATA.meta });
  const verified = Boolean(prov.source);

  // Live confidence score (link FK is d.sf); nowYear from meta.generatedAt.
  const nowYear = new Date(DATA.meta?.generatedAt || Date.now()).getUTCFullYear();
  const src = STATE.sourceIndex?.[d.sf];
  const score = confidenceScore(d, {
    sourceIndex: STATE.sourceIndex,
    meta: DATA.meta,
    sourceYear: src ? sourceYear(src, nowYear) : null,
    now: nowYear,
  });

  tt.innerHTML = `
    <div class="tn">${linkNodeLabel(d.source)} → ${linkNodeLabel(d.target)}</div>
    <div class="tf">Relationship · ${badgeHtml(prov)} · Confidence: ${score}%</div>
    <div class="td">
      <div class="td-col">
        <div class="td-item">
          <span class="td-label">Type</span>
          <span class="td-value">${d.k || "flow"}</span>
        </div>
        <div class="td-item">
          <span class="td-label">Weight</span>
          <span class="td-value">${d.v || 1}</span>
        </div>
      </div>
      <div class="td-col">
        <div class="td-item">
          <span class="td-label">Note</span>
          <span class="td-value">${d.n || "Supply-chain relationship"}</span>
        </div>
        ${verified ? `
          <div class="td-item">
            <span class="td-label">Source</span>
            <span class="td-value">✓ Verified</span>
          </div>
        ` : ''}
      </div>
    </div>
    ${prov.source ? `
      <div class="tu">
        <a href="${prov.source.url}" target="_blank" rel="noopener noreferrer" class="source-link">View Source →</a>
      </div>
    ` : ''}
  `;
  
  moveTooltip(ev);
  tt.style.display = 'block';
}

function moveTooltip(ev) {
  let x = ev.clientX + 14;
  let y = ev.clientY - 10;
  if (x + 450 > W) x = ev.clientX - 460;
  if (y + 250 > H) y = H - 260;
  tt.style.left = `${x}px`;
  tt.style.top = `${y}px`;
}

function connected(id) {
  const all = new Set([id]);
  const up = new Set();
  const down = new Set();
  STATE.links.forEach((l) => {
    const s = typeof l.source === "object" ? l.source.id : l.source;
    const t = typeof l.target === "object" ? l.target.id : l.target;
    if (s === id) { down.add(t); all.add(t); }
    if (t === id) { up.add(s); all.add(s); }
  });
  return { all, up, down };
}

function highlightNode(d) {
  const conn = connected(d.id);
  nodeSel.select(".mc").transition().duration(150).attr("fill-opacity", (n) => conn.all.has(n.id) ? 0.95 : 0.05);
  labelSel.transition().duration(150).attr("fill-opacity", (n) => conn.all.has(n.id) ? 1 : 0.05);
  subSel.transition().duration(150).attr("fill-opacity", (n) => conn.all.has(n.id) ? 1 : 0.05);
  linkSel.transition().duration(150)
    .attr("stroke-opacity", (l) => {
      const s = typeof l.source === "object" ? l.source.id : l.source;
      const t = typeof l.target === "object" ? l.target.id : l.target;
      return (s === d.id || t === d.id) ? 1 : 0.03;
    })
    .attr("stroke", (l) => {
      const s = typeof l.source === "object" ? l.source.id : l.source;
      const t = typeof l.target === "object" ? l.target.id : l.target;
      if (s === d.id) return "var(--acc)";
      if (t === d.id) return "var(--blue)";
      return "#111";
    })
    .attr("stroke-width", (l) => {
      const s = typeof l.source === "object" ? l.source.id : l.source;
      const t = typeof l.target === "object" ? l.target.id : l.target;
      return (s === d.id || t === d.id) ? 2 : 0.3;
    });
}

function resetHighlight() {
  nodeSel.select(".mc").transition().duration(180).attr("fill-opacity", (d) => d.bn ? 0.82 : 0.35);
  labelSel.transition().duration(180).attr("fill-opacity", 1);
  subSel.transition().duration(180).attr("fill-opacity", STATE.labelsVisible ? 1 : 0);
  linkSel.transition().duration(180)
    .attr("stroke-opacity", 1)
    .attr("stroke", (d) => d.v >= 3 ? "rgba(232,69,60,.18)" : d.v >= 2 ? "#1e1e1e" : "#151515")
    .attr("stroke-width", (d) => d.v >= 3 ? 1.4 : d.v >= 2 ? 0.7 : 0.35);
}

function highlightBy(fn) {
  STATE.lockId = null;
  tt.style.display = "none";
  nodeSel.select(".mc").transition().duration(160).attr("fill-opacity", (d) => fn(d) ? 1 : 0.03);
  labelSel.transition().duration(160).attr("fill-opacity", (d) => fn(d) ? 1 : 0.03);
  subSel.transition().duration(160).attr("fill-opacity", (d) => fn(d) ? (STATE.labelsVisible ? 1 : 0) : 0.03);
  linkSel.transition().duration(160).attr("stroke-opacity", 0.015);
}

function toggleParticles() {
  STATE.particlesOn = !STATE.particlesOn;
  if (!STATE.particlesOn) {
    if (STATE.particleTimer) cancelAnimationFrame(STATE.particleTimer);
    particleLayer.selectAll("*").remove();
    return;
  }
  const step = () => {
    if (!STATE.particlesOn) return;
    const strong = STATE.links.filter((l) => l.v >= 3);
    strong.forEach((l) => {
      if (Math.random() > 0.9) return;
      const s = typeof l.source === "object" ? l.source : STATE.nodes.find((n) => n.id === l.source);
      const t = typeof l.target === "object" ? l.target : STATE.nodes.find((n) => n.id === l.target);
      if (!s || !t) return;
      particleLayer.append("circle").attr("r", 1.2).attr("fill", "var(--acc)").attr("opacity", 0.55).attr("cx", s.x).attr("cy", s.y)
        .transition().duration(1400 + Math.random() * 900).ease(d3.easeLinear)
        .attr("cx", t.x).attr("cy", t.y).attr("opacity", 0).attr("r", 0.4).remove();
    });
    STATE.particleTimer = requestAnimationFrame(() => setTimeout(step, 120));
  };
  step();
}

// Shared force-simulation tick handler. Reads the CURRENT module-level nodeSel/linkSel
// (reassigned by updateGraph each view change) — never a stale closure — and applies the
// canvas boundary clamp (topPad 78 / bottomPad 20 / m = (z||10)+12) on every tick.
function ticked() {
  STATE.nodes.forEach((n) => {
    const m = (n.z || 10) + 12;
    const topPad = 78;
    const bottomPad = 20;
    n.x = Math.max(m, Math.min(W - m, n.x));
    n.y = Math.max(topPad + m, Math.min(H - bottomPad - m, n.y));
  });
  if (linkSel) linkSel.attr("x1", (d) => d.source.x).attr("y1", (d) => d.source.y).attr("x2", (d) => d.target.x).attr("y2", (d) => d.target.y);
  if (nodeSel) nodeSel.attr("transform", (d) => `translate(${d.x},${d.y})`);
}

// Build the force simulation EXACTLY ONCE (idempotent). View changes never recreate it —
// updateGraph() re-binds nodes/links and re-tunes the mode-dependent forces in place.
// Forces are created with no node argument; mode-dependent values are set by updateGraph.
function buildSimulation() {
  if (STATE.simulation) return STATE.simulation;
  STATE.simulation = d3.forceSimulation()
    .force("link", d3.forceLink().id((d) => d.id).distance((d) => d.v >= 3 ? 70 : 110).strength((d) => (d.v || 1) * 0.11))
    .force("charge", d3.forceManyBody())
    .force("x", d3.forceX())
    .force("y", d3.forceY())
    .force("collision", d3.forceCollide().radius((d) => (d.z || 10) + 8))
    .alphaDecay(0.016)
    .on("tick", ticked);
  return STATE.simulation;
}

// Attach the standard children (bn-ring, .mc circle with verified-node class, label/sub/
// country texts) to a freshly entered node <g>. Used by updateGraph's enter selection.
function buildNodeChildren(sel) {
  sel.filter((d) => d.bn).append("circle").attr("r", (d) => (d.z || 10) + 5).attr("class", "bn-ring");
  sel.append("circle").attr("class", "mc").attr("r", (d) => d.z || 10)
    .attr("fill", (d) => DATA.countries[d.c]?.c || "#777")
    .attr("fill-opacity", (d) => d.bn ? 0.82 : 0.35)
    .attr("stroke", (d) => d.bn ? "var(--acc)" : "#222")
    .attr("stroke-width", (d) => d.bn ? 1.4 : 0.5)
    .classed("verified-node", (d) => {
      const prov = provenanceFor(d, { sourceIndex: STATE.sourceIndex, meta: DATA.meta });
      return prov.tag === "observed" && Boolean(prov.source);
    });

  sel.append("text")
    .text((d) => d.l.split("\n")[0])
    .attr("dy", (d) => -(d.z || 10) - 4)
    .attr("text-anchor", "middle")
    .attr("fill", (d) => d.bn ? "#ccc" : "#666")
    .attr("font-size", (d) => d.z >= 18 ? "9px" : "7px")
    .attr("font-family", "'JetBrains Mono',monospace")
    .attr("pointer-events", "none")
    .attr("class", "node-label");

  sel.append("text")
    .text((d) => d.l.split("\n")[1] || "")
    .attr("dy", (d) => -(d.z || 10) + 6)
    .attr("text-anchor", "middle")
    .attr("fill", "#444")
    .attr("font-size", "6px")
    .attr("font-family", "'JetBrains Mono',monospace")
    .attr("pointer-events", "none")
    .attr("class", "node-sub");

  sel.append("text")
    .text((d) => d.c)
    .attr("dy", (d) => (d.z || 10) + 11)
    .attr("text-anchor", "middle")
    .attr("font-size", "7px")
    .attr("fill", "#333")
    .attr("font-family", "'JetBrains Mono',monospace")
    .attr("pointer-events", "none");
}

// Wire the node-level drag + mouse/click handlers onto a node selection.
function wireNodeHandlers(sel) {
  sel.attr("cursor", "pointer")
    .attr("role", "button")
    .attr("tabindex", 0)
    .attr("aria-label", (d) => {
      const label = d.name || d.n || d.symbol || d.id || "Supply-chain entity";
      return `Open ${label}`;
    })
    .on("keydown", (ev, d) => {
      if (ev.key !== "Enter" && ev.key !== " ") return;
      ev.preventDefault();
      activateNode(ev, d);
    })
    .call(d3.drag()
      // clickDistance lets a near-stationary press still emit a real click (mouse).
      .clickDistance(TAP_SLOP)
      .on("start", (e, d) => {
        if (!e.active) STATE.simulation.alphaTarget(0.06).restart();
        d.fx = d.x; d.fy = d.y;
        nodeDragStart = { x: e.x, y: e.y };
      })
      .on("drag", (e, d) => { d.fx = e.x; d.fy = e.y; })
      .on("end", (e, d) => {
        if (!e.active) STATE.simulation.alphaTarget(0);
        d.fx = null; d.fy = null;
        // Touch tap recovery: d3.drag() preventDefaults the touchstart, which
        // suppresses the browser's synthesized click on touch — so without this,
        // tapping a node on a phone did nothing (a real mobile defect). For a
        // TOUCH gesture that did not move (< TAP_SLOP px), activate the node here
        // (the same path as a mouse click). Mouse still uses the click handler
        // below, so this branch is touch-only to avoid double activation.
        const src = e.sourceEvent;
        const isTouch = src && (src.type.startsWith("touch") || src.pointerType === "touch");
        if (!isTouch || !nodeDragStart) { nodeDragStart = null; return; }
        const moved = Math.hypot(e.x - nodeDragStart.x, e.y - nodeDragStart.y);
        nodeDragStart = null;
        if (moved <= TAP_SLOP) activateNode(e.sourceEvent || e, d);
      }))
    .on("mouseenter", (ev, d) => {
      if (STATE.mode === "global" && d.symbol) {
        STATE.hoverSymbol = d.symbol;
        updateCompanyCard();
      }
      if (!STATE.lockId) { showTooltip(d, ev); highlightNode(d); }
    })
    .on("mousemove", (ev) => { if (!STATE.lockId) moveTooltip(ev); })
    .on("mouseleave", () => {
      if (STATE.mode === "global") {
        STATE.hoverSymbol = null;
        updateCompanyCard();
      }
      if (!STATE.lockId) { tt.style.display = "none"; resetHighlight(); }
    })
    // Mouse click activates the node. (Touch is handled in the drag `end`
    // handler above, because d3.drag suppresses the synthetic click on touch.)
    .on("click", (ev, d) => activateNode(ev, d));
}

// Shared node activation for both mouse click and touch tap (see wireNodeHandlers).
function activateNode(ev, d) {
  ev.stopPropagation();
  if (STATE.mode === "global" && d.symbol && DATA.profiles[d.symbol]) {
    openProfile(d.symbol);
    return;
  }
  if (STATE.lockId === d.id) {
    STATE.lockId = null;
    tt.style.display = "none";
    resetHighlight();
  } else {
    STATE.lockId = d.id;
    showTooltip(d, ev);
    highlightNode(d);
  }
}

// Wire the link-level mouse handlers onto a link selection.
function wireLinkHandlers(sel) {
  sel.attr("marker-end", "url(#a)")
    .attr("cursor", "pointer")
    .on("mouseenter", (ev, d) => { if (!STATE.lockId) showLinkTooltip(d, ev); })
    .on("mousemove", (ev) => { if (!STATE.lockId) moveTooltip(ev); })
    .on("mouseleave", () => { if (!STATE.lockId) tt.style.display = "none"; });
}

// Update on EVERY view change: carry positions (mental map), re-tune forces in place,
// data-join enter/update/exit with reduced-motion-gated transitions, re-bind the SAME
// simulation's nodes/links, then gently reheat (alphaTarget(0.3) → 0). Never a
// from-scratch full reheat, never a new d3.forceSimulation.
function updateGraph(graph) {
  const sim = buildSimulation();

  // 1. MENTAL MAP: carry x/y/vx/vy from prior nodes by id. graph.nodes already carry
  //    computed band/profile SEED positions (set by render's layout pass); existing nodes
  //    overwrite those seeds with their settled prior positions so they don't fly in.
  const prev = new Map(STATE.nodes.map((n) => [n.id, n]));
  graph.nodes.forEach((n) => {
    const p = prev.get(n.id);
    if (p) { n.x = p.x; n.y = p.y; n.vx = p.vx; n.vy = p.vy; }
  });
  STATE.nodes = graph.nodes;
  STATE.links = graph.links;

  // 2. Re-tune the mode-dependent forces IN PLACE (same values as the old inline forceSimulation).
  sim.force("charge").strength(STATE.mode === "global" ? -180 : -220);
  sim.force("x").x((d) => STATE.mode === "global" ? W / 2 : d.targetX).strength(STATE.mode === "global" ? 0.03 : 0.25);
  sim.force("y").y((d) => d.targetY).strength(STATE.mode === "global" ? 0.4 : 0.14);

  // 3. Data-join links + nodes with reduced-motion-gated enter/exit transitions.
  const dur = prefersReducedMotion() ? 0 : 350;

  linkSel = linkLayer.selectAll("line").data(STATE.links, (d) => {
    const s = typeof d.source === "object" ? d.source.id : d.source;
    const t = typeof d.target === "object" ? d.target.id : d.target;
    return `${s}->${t}`;
  }).join(
    (enter) => {
      const line = enter.append("line")
        .attr("stroke-opacity", 0);
      wireLinkHandlers(line);
      line.transition().duration(dur).ease(d3.easeCubic).attr("stroke-opacity", 1);
      return line;
    },
    (update) => update,
    (exit) => exit.call((e) => e.transition().duration(dur).ease(d3.easeCubic).attr("stroke-opacity", 0).remove()),
  );
  // Keep static link styling current for both entering and updating links.
  linkSel.attr("stroke", (d) => d.v >= 3 ? "rgba(232,69,60,.18)" : d.v >= 2 ? "#1e1e1e" : "#151515")
    .attr("stroke-width", (d) => d.v >= 3 ? 1.4 : d.v >= 2 ? 0.7 : 0.35);

  nodeSel = nodeLayer.selectAll("g.node").data(STATE.nodes, (d) => d.id).join(
    (enter) => {
      const grp = enter.append("g").attr("class", "node").attr("opacity", 0);
      buildNodeChildren(grp);
      wireNodeHandlers(grp);
      grp.transition().duration(dur).ease(d3.easeCubic).attr("opacity", 1);
      return grp;
    },
    (update) => update,
    (exit) => exit.call((e) => e.transition().duration(dur).ease(d3.easeCubic).attr("opacity", 0).remove()),
  );
  // Refresh module-level child selections used by highlight/reset functions.
  labelSel = nodeSel.select(".node-label");
  subSel = nodeSel.select(".node-sub");

  // 4. Re-bind data to the SAME simulation (re-initializes bound forces; carried positions stay).
  const simulation = sim;
  simulation.nodes(STATE.nodes);
  simulation.force("link").links(STATE.links);

  // 5. GENTLE reheat — warm toward 0.3, then settle to 0 after ~600ms (never a full reheat).
  if (STATE.settleTimer) clearTimeout(STATE.settleTimer);
  if (prefersReducedMotion()) {
    // Reduced motion: skip the visible reheat, snap toward a settled layout.
    sim.alphaTarget(0).alpha(0.05).restart();
    STATE.settleTimer = setTimeout(() => sim.stop(), 0);
  } else {
    sim.alphaTarget(0.3).restart();
    STATE.settleTimer = setTimeout(() => sim.alphaTarget(0), 600);
  }
}

// Stable layers created once so they survive view changes. z-order (append order):
// bands (back) → links → particles → nodes (front). Bands are redrawn per view; the
// link/node/particle groups persist so the data-join + particle timer keep working.
let bandLayer;
let linkLayer;
let nodeLayer;

function ensureLayers() {
  if (bandLayer && linkLayer && nodeLayer && particleLayer) return;
  bandLayer = g.append("g").attr("class", "bands");
  linkLayer = g.append("g").attr("class", "links");
  particleLayer = g.append("g").attr("class", "particles");
  nodeLayer = g.append("g").attr("class", "nodes");
}

// Public entry. Builds graph for the current mode, updates chrome + layer bands, then
// delegates node/link binding + simulation to updateGraph (build-once / update-on-change).
// NO clearGraph() on a view change — that teardown is what caused the jank (STORY-03).
function render() {
  hideSearchPopovers();
  const graph = graphForMode();
  STATE.nodes = graph.nodes;
  STATE.links = graph.links;
  STATE.layerMap = graph.layers;
  STATE.sourceIndex = graph.sourceIndex || {};

  productTitleEl.textContent = STATE.mode === "global"
    ? "Supply Chain Intelligence"
    : `Supply Chain Intelligence — ${STATE.symbol} profile`;
  subtitleEl.textContent = graph.subtitle;
  hintEl.textContent = graph.hint;
  document.getElementById("bBack").style.display = STATE.mode === "profile" ? "inline-block" : "none";
  jump.value = STATE.mode === "profile" ? STATE.symbol : "";
  document.getElementById("fConfidence").value = STATE.filters.confidence;
  document.getElementById("fType").value = STATE.filters.type;
  document.getElementById("fVerified").value = STATE.filters.verified;

  // #lastUpdated is owned solely by js/ui updateStatusIndicator (RESEARCH Pitfall 2:
  // dual-owner freshness hazard). The viz no longer writes it.

  updateCompanyCard();
  updateCompareButton();

  updateStats();
  buildLegend();
  buildLayerSidebar();
  buildCountryButtons();

  ensureLayers();

  // Layer bands + labels are view-specific chrome: redraw them each view change.
  bandLayer.selectAll("*").remove();
  const layerKeys = [...new Set(STATE.nodes.map((n) => n.layer))].sort((a, b) => a - b);
  const bandH = H / Math.max(1, layerKeys.length);

  layerKeys.forEach((layer, i) => {
    const y = (layerKeys.length - 1 - i) * bandH;
    if (STATE.mode === "global") {
      bandLayer.append("rect").attr("x", -10000).attr("y", y).attr("width", 20000).attr("height", bandH)
        .attr("fill", i % 2 === 0 ? "#0d0d0d" : "transparent").attr("pointer-events", "none");
    }
    bandLayer.append("text")
      .attr("x", STATE.mode === "global" ? -9950 : 40)
      .attr("y", y + 16)
      .attr("fill", "#1e1e1e")
      .attr("font-size", "10px")
      .attr("font-family", "'Bricolage Grotesque',sans-serif")
      .text(STATE.layerMap[layer] || "")
      .attr("pointer-events", "none");
  });

  // Seed positions for NEW nodes (existing nodes have their carried positions restored in
  // updateGraph by id). Always compute targetX/targetY so the forces aim correctly.
  STATE.nodes.forEach((n) => {
    if (STATE.mode === "global") {
      const idx = layerKeys.indexOf(n.layer);
      n.targetY = (layerKeys.length - 1 - idx) * bandH + bandH * 0.5;
      n.x = W * 0.1 + Math.random() * W * 0.8;
      n.y = n.targetY + (Math.random() - 0.5) * bandH * 0.2;
    } else {
      n.targetX = 0;
      n.targetY = 0;
      n.x = W * 0.5 + (Math.random() - 0.5) * 40;
      n.y = H * 0.5 + (Math.random() - 0.5) * 40;
    }
  });

  if (STATE.mode === "profile") {
    const groupByLayer = new Map(layerKeys.map((layer) => [layer, []]));
    STATE.nodes.forEach((n) => {
      groupByLayer.get(n.layer).push(n);
    });
    layerKeys.forEach((layer, i) => {
      const arr = groupByLayer.get(layer).sort((a, b) => (a.kind > b.kind ? 1 : -1));
      const x = (i + 1) * (W / (layerKeys.length + 1));
      const spacing = Math.max(70, Math.min(120, (H * 0.62) / Math.max(1, arr.length)));
      const startY = H * 0.52 - ((arr.length - 1) * spacing) / 2;
      arr.forEach((n, j) => {
        n.targetX = x;
        n.targetY = startY + j * spacing;
        n.x = n.targetX + (Math.random() - 0.5) * 20;
        n.y = n.targetY + (Math.random() - 0.5) * 20;
      });
    });
  }

  svg.on("click", () => {
    if (STATE.lockId) {
      STATE.lockId = null;
      tt.style.display = "none";
      resetHighlight();
    }
  });

  // Delegate node/link binding + the single simulation to updateGraph (carry positions,
  // gentle reheat). graph already holds STATE.nodes (with seeds) — pass it through.
  updateGraph(graph);

  svg.transition().duration(prefersReducedMotion() ? 0 : 450).call(zoom.transform, d3.zoomIdentity.scale(0.8));
  syncUrlState();
}

export {
  svg, g, zoom, W, H, tt, labelSel, subSel,
  render, clearGraph, updateStats, buildLegend, buildLayerSidebar, buildCountryButtons,
  showTooltip, linkNodeLabel, showLinkTooltip, moveTooltip, connected, highlightNode,
  resetHighlight, highlightBy, toggleParticles, animateCounter,
};
